// ==================================================
// REFLECTION — GET CONTEXT
// ==================================================

// 1. GET CONVERSATION ID FROM WEBHOOK
// ==================================================

const webhook = $('conversation-rejected').first().json;

const conversationId =
  webhook.body?.conversation_id ||
  webhook.conversation_id;

if (!conversationId) {
  throw new Error(
    `Missing conversation_id: ${JSON.stringify(webhook)}`
  );
}


// ==================================================
// 2. SUPABASE CONNECTION
// ==================================================

const supabaseUrl = 'https://jikdykibhyewrfnlpptv.supabase.co';
const supabaseKey = 'sb_secret_1g3-NRYivFEIBV415V3tnw_GcnjqMkI';

const headers = {
  apikey: supabaseKey,
  Authorization: `Bearer ${supabaseKey}`,
  'Content-Type': 'application/json'
};


// ==================================================
// 3. SUPABASE GET HELPER
// ==================================================

async function supabaseGet(table, query) {
  try {
    return await this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/${table}?${query}`,
      headers
    });
  } catch (error) {
    throw new Error(
      `Supabase GET failed for table "${table}": ${
        error.message || error
      }`
    );
  }
}


// ==================================================
// 4. GET CONVERSATION
// ==================================================

const conversations = await supabaseGet(
  'conversations',
  `select=id,customer_id,channel,status,queue,language,intent,sentiment,urgency_score,order_id,order_number,created_at,updated_at` +
  `&id=eq.${conversationId}`
);

const conversation = conversations[0];

if (!conversation) {
  throw new Error(
    `Conversation not found: ${conversationId}`
  );
}


// ==================================================
// 5. GET CUSTOMER
// ==================================================

const customers = await supabaseGet(
  'customers',
  `select=id,full_name,email,phone` +
  `&id=eq.${conversation.customer_id}`
);

const customer = customers[0] || null;


// ==================================================
// 6. GET CUSTOMER MESSAGE
// ==================================================
//
// Get the latest customer message.
// This is the message that the AI was responding to.
//

const customerMessages = await supabaseGet(
  'messages',
  `select=id,conversation_id,sender_type,sender_id,content,created_at` +
  `&conversation_id=eq.${conversationId}` +
  `&sender_type=eq.customer` +
  `&order=created_at.desc` +
  `&limit=1`
);

const customerMessage = customerMessages[0] || null;

if (!customerMessage) {
  throw new Error(
    `No customer message found for conversation: ${conversationId}`
  );
}


// ==================================================
// 7. GET PREVIOUS AI ANSWER
// ==================================================
//
// message_versions contains:
// - message_id
// - version_number
// - content
// - author_type
// - author_id
// - conversation_id
//
// We retrieve the latest AI-generated version.
//

const aiVersions = await supabaseGet(
  'message_versions',
  `select=id,message_id,version_number,content,author_type,author_id,created_at,conversation_id` +
  `&conversation_id=eq.${conversationId}` +
  `&author_type=eq.ai` +
  `&order=version_number.desc` +
  `&limit=1`
);

const previousAiVersion = aiVersions[0] || null;

if (!previousAiVersion) {
  throw new Error(
    `No AI message version found for conversation: ${conversationId}`
  );
}


// ==================================================
// 8. GET ORDER
// ==================================================

let order = null;

if (conversation.order_number) {

  const orders = await supabaseGet(
    'orders',
    `select=id,customer_id,order_number,status,total_amount,currency,ordered_at,expected_delivery_at,delivered_at,tracking_number` +
    `&customer_id=eq.${conversation.customer_id}` +
    `&order_number=eq.${encodeURIComponent(
      conversation.order_number
    )}`
  );

  order = orders[0] || null;
}


// ==================================================
// 9. GET RAG SOURCES
// ==================================================
//
// IMPORTANT:
// We currently do not have a confirmed table that links
// message_versions to faq_chunks.
//
// Therefore we leave sources empty rather than inventing
// which chunks were used.
//
// Later, if you have something like:
//
// message_version_sources
// -----------------------
// message_version_id
// chunk_id
// similarity
//
// we can retrieve the exact sources here.
//

const sources = [];


// ==================================================
// 10. RETURN REFLECTION CONTEXT
// ==================================================

return [
  {
    json: {

      // ----------------------------------------------
      // CONVERSATION
      // ----------------------------------------------

      conversation: {
        id: conversation.id,
        status: conversation.status,
        intent: conversation.intent,
        language: conversation.language,
        sentiment: conversation.sentiment,
        urgency_score: conversation.urgency_score
      },


      // ----------------------------------------------
      // CUSTOMER
      // ----------------------------------------------

      customer: customer
        ? {
            id: customer.id,
            full_name: customer.full_name,
            email: customer.email,
            phone: customer.phone
          }
        : null,


      // ----------------------------------------------
      // CUSTOMER MESSAGE
      // ----------------------------------------------

      customer_message: {
        id: customerMessage.id,
        content: customerMessage.content,
        created_at: customerMessage.created_at
      },


      // ----------------------------------------------
      // PREVIOUS AI ANSWER
      // ----------------------------------------------

      previous_ai_answer: {
        message_id: previousAiVersion.message_id,
        version: previousAiVersion.version_number,
        content: previousAiVersion.content
      },


      // ----------------------------------------------
      // RAG SOURCES
      // ----------------------------------------------

      sources,


      // ----------------------------------------------
      // ORDER
      // ----------------------------------------------

      order: order
        ? {
            order_number: order.order_number,
            status: order.status,
            tracking_number: order.tracking_number
          }
        : null
    }
  }
];

