const output = $('Reflection generation').first().json;

if (!output.text) {
  throw new Error('Missing Reflection output.');
}

let data;

try {
  data = JSON.parse(output.text);
} catch (error) {
  throw new Error(`Invalid Reflection JSON: ${error.message}`);
}

if (!data.answer) {
  throw new Error('Reflection JSON does not contain answer.');
}

return [
  {
    json: {
      answer: data.answer
    }
  }
];
